def cached(cache, key=hashkey, lock=None):
	"""
	Returns a decorator function that saves the results in the cache
	"""
	def decorator(func):
		@wraps(func)
		def wrapper(*args, **kwargs):
			if not hasattr(wrapper, 'cache'):
				wrapper.cache = cache
			if not hasattr(wrapper, 'lock'):
				wrapper.lock = lock
			if not hasattr(wrapper, 'key'):
				wrapper.key = key
			key_ = wrapper.key(args, kwargs)
			with wrapper.lock:
				result = wrapper.cache.get(key_)
			if result is None:
				result = func(*args, **kwargs)
				with wrapper.lock:
					wrapper.cache[key_] = result
			return result
		return wrapper
	return decorator

def mru_cache(maxsize=128, typed=False):
	"""
	Decorator to wrap a function with a memoizing callable that saves
up to `maxsize` results based on a Most Recently Used (MRU)
algorithm.
	"""
	def decorating_function(user_function):
		if not isinstance(maxsize, int) or maxsize < 0:
			raise ValueError("maxsize must be a non-negative integer")
		if not isinstance(typed, bool):
			raise TypeError("typed must be a boolean")

		cache = collections.OrderedDict()

		def wrapper(*args, **kwargs):
			key = _make_key(args, kwargs, typed)
			try:
				return cache[key]
			except KeyError:
				pass
			except TypeError:
				# unhashable type: 'list'
				result = user_function(*args, **kwargs)
				cache[key] = result
				return result

		def clear():
			cache.clear()

		wrapper.cache_info = lambda: len(cache)
		wrapper.cache_clear = clear
		wrapper.maxsize = maxsize
		wrapper.mru = lambda: list(cache.keys())[-1]

		return functools.update_wrapper(wrapper, user_function)

	return decorating_function

