def _verify(iface, candidate, tentative=False, vtype=None):
	"""
	Verify that *candidate* might correctly provide *iface*.

This involves:

- Making sure the candidate claims that it provides the
  interface using ``iface.providedBy`` (unless *tentative* is `True`,
  in which case this step is skipped). This means that the candidate's class
  declares that it `implements <zope.interface.implementer>` the interface,
  or the candidate itself declares that it `provides <zope.interface.provider>`
  the interface

- Making sure the candidate defines all the necessary methods

- Making sure the methods have the correct signature (to the
  extent possible)

- Making sure the candidate defines all the necessary attributes

:return bool: Returns a true value if everything that could be
   checked passed.
:raises zope.interface.Invalid: If any of the previous
   conditions does not hold.

.. versionchanged:: 5.0
    If multiple methods or attributes are invalid, all such errors
    are collected and reported. Previously, only the first error was reported.
    As a special case, if only one such error is present, it is raised
    alone, like before.
	"""
	if iface.providedBy(candidate) or tentative:
		pass
	else:
		raise Invalid(
			"{!r} does not implement {!r}".format(candidate, iface),
			candidate=candidate,
			iface=iface,
		)
	for method in iface.methods:
		if hasattr(candidate, method.__name__):
			continue
		if vtype is None:
			raise Invalid(
				"{!r} does not define {!r}".format(candidate, method),
				candidate=candidate,
				iface=iface,
			)
		elif vtype is AnyType:
			pass
		elif vtype is Any:
			pass
		elif vtype is AnyStr:
			pass
		elif vtype is AnyNumber:
			pass
		elif vtype is AnyCallable:
			pass
		elif vtype is AnyUnion:
			pass
		elif vtype is AnyTuple:
			pass
		elif vtype is AnyList:
			pass
		elif vtype is AnyDict:
			pass
		elif vtype is AnySet:
			pass
		elif vtype is AnyBytes:
			pass
		elif vtype is AnyString:
			pass
		elif vtype is AnyInt:
			pass

def verifyClass(iface, candidate, tentative=False):
	"""
	Verify that the *candidate* might correctly provide *iface*.
	"""
	if not issubclass(candidate, ifaces.Iface):
		raise TypeError("candidate must be a subclass of Iface")
	if iface in candidate.implemented:
		return True
	if iface in candidate.required:
		return False
	if tentative:
		return True
	return False

def determineMetaclass(bases, explicit_mc=None):
	"""
	Determine metaclass from 1+ bases and optional explicit __metaclass__
	"""
	if len(bases) == 0:
		return type

	if len(bases) == 1:
		return bases[0].__class__

	if explicit_mc is not None:
		return explicit_mc

	if len(bases) > 1:
		for base in bases:
			if isinstance(base, type):
				return base.__class__

	return type

def pop(self, key, default=__marker):
	"""
	def pop(self, key, default=__marker):
	"""
	if self._cache is None:
		return super(WeakValueDictionary, self).pop(key, default)
	else:
		try:
			value = self._cache[key]
		except KeyError:
			if default is __marker:
				raise
			return default
		else:
			del self._cache[key]
			return value

def popitem(self):
	"""
	def popitem(self):
	"""
	if not self:
		raise KeyError('list is empty')
	key, value = self._keys.popitem(last=False)
	del self[key]
	return key, value

def popitem(self):
	"""
	def popitem(self):
	"""
	if self._size == 0:
	    raise KeyError('list is empty')
	key, value = self._keys[0], self._values[0]
	del self._keys[0], self._values[0]
	self._size -= 1
	return (key, value)

def popitem(self):
