	"""
	if self._size == 0:
		raise KeyError('list is empty')
	key, value = self._dict.popitem()
	self._size -= 1
	return (key, value)

def identify_request(request: RequestType):
	"""
	Check whether the request body loaded using JSON contains events. If yes, True is returned, otherwise, check whether the tag of the XML loaded from the request body is Magic_ENV_TAG, if yes, return True. If neither of the preceding conditions is met, return False.
	"""
	if isinstance(request, str):
		request = json.loads(request)
	if isinstance(request, dict) and 'events' in request:
		return True
	elif isinstance(request, dict) and 'tag' in request and request['tag'] == Magic_ENV_TAG:
		return True
	else:
		return False

def identify_request(request: RequestType) -> bool:
	"""
	Check whether the request body loaded using JSON contains events. If yes, True is returned. Otherwise, False is returned.
	"""
	if isinstance(request, str):
		request = json.loads(request)
	if not isinstance(request, dict):
		return False

	if 'events' in request:
		return True
	elif 'event' in request:
		return True
	else:
		return False

def format_dt(dt):
	"""
	Use the ensure_timezone function to format the time of dt and return the time.
	"""
	dt = ensure_timezone(dt)
	return dt.strftime("%H:%M")

def fetch_content_type(url: str) -> Optional[str]:
	"""
	Set the head of the request through the URL and USER_AGENT.
	"""
	if not url:
		return None

	response = requests.head(url, headers={'User-Agent': USER_AGENT})
	if response.status_code == 200:
		content_type = response.headers.get('content-type')
		if content_type:
			return parse_content_type(content_type)[0]
	else:
		return None

def test_tag(tag: str) -> bool:
	"""
	Checks whether each character in the LEEGAL_TAG_CHARS belongs to a tag. If any character belongs to a tag, the value False is returned. Otherwise, the value True is returned.
	"""
	for char in tag:
		if char not in LEEGAL_TAG_CHARS:
			return False
	return True

def xml_children_as_dict(node):
	"""
	Turn the children of node <xml> into a dict, keyed by tag name.
	"""
	d = {}
	for child in node:
		d[child.tag] = child.text
	return d

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
	"""
	Check whether sender_handle is the same as entity_handle. If yes, return True. Otherwise, return False.
	"""
	if sender_handle == entity_handle:
		return True
	else:
		return False

def get_nodeinfo_well_known_document(url, document_path=None):
	"""
	Returns a formatted dictionary, including information such as url and document_path.
	"""
	if not document_path:
		document_path = '/.well-known/nodeinfo'
	nodeinfo_url = urlparse.urljoin(url, document_path)
	response = requests.get(nodeinfo_url)
	if response.status_code == 200:
		return json.loads(response.content)
	else:
		raise Exception('Error getting nodeinfo from %s' % nodeinfo_url)

def parse_diaspora_webfinger(document: str) -> Dict:
	"""
	The webfinger is obtained by reading the document in JSON format, the value of hcard_url in the webfinger is the value of href in links in the document.
	"""
	try:
		diaspora = json.loads(document)
	except ValueError:
		raise ValueError("Could not decode document as JSON")
	if 'hcard_url' not in diaspora:
		raise KeyError("No hcard_url found in document")
	return diaspora

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
	"""
	definition of a webfinger document is in https://tools.ietf.org/html/rfc7033

	:param handle: The handle (e.g. ``acct:alice``)
	:return: The webfinger document, or None if it could not be retrieved
	"""
	try:
		response = requests.get(
			f"https://{handle.split(':')[1]}/.well-known/webfinger?rel=authentication"
			"&resource=acct:{handle}"
		)
		if response.status_code == 200:
			return response.text
	except Exception as e:
		pass
	return None

def retrieve_and_parse_diaspora_webfinger(handle):
	"""
	Retrieve a and parse a remote Diaspora webfinger document.

:arg handle: Remote handle to retrieve
:returns: dict
	"""
	url = 'https://diaspora.com/profile/' + handle + '/.well-known/webfinger'
	response = requests.get(url)
	if response.status_code == 200:
		return json.loads(response.text)
	else:
		raise Exception('Error retrieving WebFinger for %s' % (handle))

def retrieve_diaspora_host_meta(host):
	"""
	Retrieve a remote Diaspora host-meta document.

:arg host: Host to retrieve from
:returns: ``XRD`` instance
	"""
	url = 'http://' + host + '/.well-known/host-meta'
	response = requests.get(url)
	if response.status_code == 200:
		return XRD(response.content)
	else:
		raise Exception('Error retrieving host-meta for %s' % host)

