def get_deprecated_args(self):
	"""
	Returning dict with options which deprecate others. options from self.spec_helper.iterate_option_specs()
	"""
	deprecated = {}
	for spec in self.spec_helper.iterate_option_specs():
		if not isinstance(spec, OptionSpec) or not spec.deprecated:
			continue
		deprecated[spec.name] = spec
	return deprecated

def validate_arg_deprecation(self, cli_args, answer_file_args):
	"""
	Validates and prints the deprecated arguments.

:param cli_args: the dict of arguments from cli
:param answer_file_args:  the dict of arguments from files
	"""
	for arg in self.deprecated_args:
		if arg in cli_args or arg in answer_file_args:
			self.printer("The argument %s is deprecated and will be removed soon." % arg)
			if arg in cli_args:
				del cli_args[arg]
			if arg in answer_file_args:
				del answer_file_args[arg]

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                   spec_option):
	"""
	Returns the corresponding function in COMPLEX_TYPES based on type_name and returns the result obtained by complex_action after option_name,(self.vars, self.defaults, self.plugin_path), subcommand, spec_option) is input.
	"""
	if type_name not in COMPLEX_TYPES:
		raise ValueError("type_name %s not supported" % (type_name))
	return COMPLEX_TYPES[type_name](subcommand, option_name, spec_option)

def get_nested_custom_and_control_args(self, args):
	"""
	def get_nested_custom_and_control_args(self, args):
	"""
	"""
	Split input arguments to control nested and custom.

Controls arguments: control the IR behavior. These arguments
    will not be put into the spec yml file
Nested arguments: are used by the Ansible playbooks and will be put
    into the spec yml file.
Custom arguments: Custom ansible variables to be used instead of the
    normal nested usage.

:param args: the collected list of args.
:return: (dict, dict): flat dicts (control_args, nested_args)
	"""
	control_args = {}
	nested_args = {}

	for arg in args:
		if isinstance(arg, NestedArg):
			nested_args[arg.name] = arg
		elif isinstance(arg, ControlArg):
			control_args[arg.name] = arg
		else:
			raise TypeError("Unexpected argument type: {}".format(type(arg)))

	return control_args, nested_args

def _convert_non_cli_args(self, parser_name, values_dict):
	"""
	Casts arguments to correct types by modifying values_dict param.

By default all the values are strings.

:param parser_name: The command name, e.g. main, virsh, ospd, etc
:param values_dict: The dict of with arguments
	"""
	if not self._non_cli_args:
		return

	for arg in self._non_cli_args:
		arg_name = arg['name']
		arg_type = arg['type']

		if arg_name in values_dict:
			if arg_type == 'bool':
				values_dict[arg_name] = bool(values_dict[arg_name])
			elif arg_type == 'int':
				values_dict[arg_name] = int(values_dict[arg_name])
			elif arg_type == 'float':
				values_dict[arg_name] = float(values_dict[arg_name])
			elif arg_type == 'strlist':
				values_dict[arg_name] = [x.strip() for x in values_dict[arg_name].split(',')]
			elif arg_type == 'dict':
				values_dict[arg_name] = json.loads(values_dict[arg_name])
			elif arg_type == 'list':
				values_dict[arg_name] = ast.literal_eval(values_dict[arg_name])

			if arg.get('cast'):
				values_dict[arg_name] = arg['cast'](values_dict[arg_name])

			if arg.get('cast_str'):
				values_dict[arg_name] = str(values_dict[arg_name])

			if arg.get('cast_int'):
				values_dict[arg_name] = int(values_dict[arg_name])

			if arg.get('cast_float'):
				values_dict[arg_name] = float(values_dict[arg_name])

			if arg.get('cast_bool'):
				values_dict[arg_name] = bool(values_dict[arg_name])

